def compute(vars):
    value = vars["v1"] - vars["v2"]
    return {
        "value": value,
        "trace": {
            "2017_exposure": vars["v1"],
            "2016_exposure": vars["v2"],
            "change": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "amount"
            }
        }
    }
